import math

def decibel(x, to="power"):
    if to == "power":
        return 10 * math.log10(x)
    elif to == "amplitude":
        return 20 * math.log10(x)



Übung 5

def product(n, k=1):
    result = 1
    for i in range(1, n + 1):
        if i % k == 0:
            result *= i
    return result

Oder noch kürzer (eleganter):

def product(n, k=1):
    result = 1
    for i in range(k, n + 1, k):
        result *= i
    return result
